"""Write docs/NODES.md (English) and docs/NODES.ru.md (Russian) from the
node registry and the interface strings, so the reference always matches the
program.

Run from the program folder:  python docs/make_node_docs.py
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.dirname(HERE))

import i18n          # noqa: E402
import nodes as ND   # noqa: E402

TITLE = {'en': ('Node reference', 'Generated by `docs/make_node_docs.py` from the program '
                'itself — do not edit by hand. Port and parameter names in brackets are the '
                'names used in project files.',
                'Inputs', 'Outputs', 'Parameters', 'optional', 'Russian version: [NODES.ru.md](NODES.ru.md).'),
         'ru': ('Справочник узлов', 'Создан скриптом `docs/make_node_docs.py` из самой '
                'программы — руками не править. В скобках — имена входов, выходов и настроек '
                'в файлах проектов.',
                'Входы', 'Выходы', 'Настройки', 'можно не подключать',
                'English version: [NODES.md](NODES.md).')}


def one(s):
    return ' '.join(str(s).split())


def write(lang, path):
    i18n.Lang.cur = lang
    t = i18n.t
    title, intro, l_in, l_out, l_par, l_opt, other = TITLE[lang]
    out = ['# ' + title, '', intro, '', other, '']
    for cat in ND.CATEGORIES:
        keys = [k for k, s in ND.REG.items() if s.cat == cat and not s.hidden]
        if not keys:
            continue
        out += ['## ' + one(t('cat.' + cat)), '']
        for k in keys:
            s = ND.REG[k]
            out += ['### %s (`%s`)' % (one(t('nd.' + k)), k), '']
            info = t('nd.%s.info' % k)
            if info and info != 'nd.%s.info' % k:
                out += [one(info), '']
            if s.ins:
                out.append('**%s:** ' % l_in + ', '.join(
                    '%s (`%s`%s)' % (one(ND.label(k, n)), n, ', ' + l_opt if n in s.opt else '')
                    for n, _ in s.ins))
                out.append('')
            if s.outs:
                out.append('**%s:** ' % l_out + ', '.join(
                    '%s (`%s`)' % (one(ND.label(k, n)), n) for n, _ in s.outs))
                out.append('')
            shown = [p for p in s.params if p[1] != 'd']
            if shown:
                out.append('**%s:**' % l_par)
                out.append('')
                for name, kind, dflt, lo, hi in shown:
                    if kind in ('f', 'i'):
                        rng = ' — %s…%s, %s' % (lo, hi, dflt)
                    elif kind == 'c':
                        rng = ' — ' + ' / '.join(str(v) for v in lo) + ', %s' % dflt
                    else:
                        rng = ' — %s' % dflt
                    h = ND.hint(k, name)
                    out.append('- %s (`%s`)%s%s' % (one(ND.label(k, name)), name, rng,
                                                    ('. ' + one(h)) if h else ''))
                out.append('')
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(out).rstrip() + '\n')


if __name__ == '__main__':
    write('en', os.path.join(HERE, 'NODES.md'))
    write('ru', os.path.join(HERE, 'NODES.ru.md'))
    i18n.Lang.cur = 'ru'
    print('docs/NODES.md, docs/NODES.ru.md written')
